package com.alpharip.staffmod.BuildTimelapse.timeline;
public final class TimelineClip {private final String id,source;private long start,duration;private double speed=1;public TimelineClip(String id,String source,long start,long duration){if(id==null||source==null||start<0||duration<0)throw new IllegalArgumentException("clip");this.id=id;this.source=source;this.start=start;this.duration=duration;}public String getId(){return id;}public String getSource(){return source;}public long getStart(){return start;}public long getDuration(){return duration;}public long getEnd(){return start+duration;}public void setStart(long v){if(v<0)throw new IllegalArgumentException();start=v;}public void setDuration(long v){if(v<0)throw new IllegalArgumentException();duration=v;}public double getSpeed(){return speed;}public void setSpeed(double v){if(v<=0||v>100||Double.isNaN(v))throw new IllegalArgumentException();speed=v;}}
